use vstd::prelude::*;

verus! {

fn concatenate(a: Vec<f32>, b: Vec<f32>) -> (result: Vec<f32>)
    ensures
        result.len() == a.len() + b.len(),
        forall|i: int| 0 <= i < a.len() ==> result[i] == a[i],
        forall|i: int| 0 <= i < b.len() ==> result[a.len() + i] == b[i],
{
    // Preallocate a new vector with enough capacity to hold all elements from both inputs
    let mut result = Vec::with_capacity(a.len() + b.len());

    // Extend the result vector with all elements of the first input vector
    result.extend_from_slice(&a);
    assert(result.len() == a.len());
    assert(forall|i: int| 0 <= i < a.len() ==> result[i] == a[i]);

    // Extend the result vector with all elements of the second input vector
    let ghost old_len = result.len();
    result.extend_from_slice(&b);
    assert(result.len() == old_len + b.len());
    assert(forall|i: int| 0 <= i < old_len ==> result[i] == a[i]);
    assert(forall|i: int| 0 <= i < b.len() ==> result[old_len + i] == b[i]);

    result
}

}

